/**
 * Parallel execution with concurrency control.
 */
/** Result of parallel execution */
export interface ParallelResult<R> {
	/** Results array - undefined entries indicate tasks that were skipped due to abort */
	results: (R | undefined)[];
	/** Whether execution was aborted before all tasks completed */
	aborted: boolean;
}

export interface MapWithConcurrencyOptions<T, R> {
	/** Dependency indexes aligned with `items`; a task may start only after all listed indexes succeed. */
	dependencies?: ReadonlyArray<ReadonlyArray<number>>;
	/** Determine whether a completed result unlocks its dependents. Defaults to always successful. */
	isSuccessful?: (result: R, index: number) => boolean;
	/** Synthesize a terminal result for tasks blocked by failed dependencies. */
	onDependencyFailure?: (item: T, index: number, failedDependencyIndexes: number[]) => Promise<R> | R;
}

type ExecutionState = "pending" | "running" | "succeeded" | "failed" | "blocked";

/**
 * Execute items with a concurrency limit using a worker pool pattern.
 * Results are returned in the same order as input items.
 *
 * Dependency-free items fan out up to the concurrency limit. Items with
 * dependencies wait until all dependency indexes complete successfully.
 *
 * On abort: returns partial results with `aborted: true`. Completed tasks are preserved,
 * in-progress tasks will complete with their abort handling, skipped tasks are `undefined`.
 *
 * On error: fails fast - does not wait for other workers to complete.
 *
 * @param items - Items to process
 * @param concurrency - Maximum concurrent operations
 * @param fn - Async function to execute for each item
 * @param signal - Optional abort signal to stop scheduling new work
 * @param options - Optional dependency metadata and blocked-task handling
 */
export async function mapWithConcurrencyLimit<T, R>(
	items: T[],
	concurrency: number,
	fn: (item: T, index: number) => Promise<R>,
	signal?: AbortSignal,
	options: MapWithConcurrencyOptions<T, R> = {},
): Promise<ParallelResult<R>> {
	if (items.length === 0) {
		return { results: [], aborted: signal?.aborted ?? false };
	}

	const normalizedConcurrency = Number.isFinite(concurrency) ? Math.floor(concurrency) : items.length;
	const effectiveConcurrency = normalizedConcurrency > 0 ? normalizedConcurrency : items.length;
	const limit = Math.max(1, Math.min(effectiveConcurrency, items.length));
	const results: (R | undefined)[] = new Array(items.length);
	const dependencyIndexes = items.map((_, index) => [...(options.dependencies?.[index] ?? [])]);
	const remainingDependencies = dependencyIndexes.map(indexes => indexes.length);
	const dependents = items.map(() => [] as number[]);
	for (let index = 0; index < dependencyIndexes.length; index++) {
		for (const dependencyIndex of dependencyIndexes[index]) {
			dependents[dependencyIndex]?.push(index);
		}
	}

	const states: ExecutionState[] = new Array(items.length).fill("pending");
	const readyQueue: number[] = [];
	for (let index = 0; index < items.length; index++) {
		if (remainingDependencies[index] === 0) {
			readyQueue.push(index);
		}
	}

	// Create internal abort controller to cancel workers on any rejection
	const abortController = new AbortController();
	const workerSignal = signal ? AbortSignal.any([signal, abortController.signal]) : abortController.signal;

	// Promise that rejects on first error - used to fail fast (not for abort)
	let rejectFirst: (error: unknown) => void;
	const firstErrorPromise = new Promise<never>((_, reject) => {
		rejectFirst = reject;
	});
	const { promise: completionPromise, resolve: resolveCompletion } = Promise.withResolvers<void>();

	const isSuccessful = options.isSuccessful ?? (() => true);
	let running = 0;
	let remaining = items.length;
	let settled = false;

	const maybeResolve = () => {
		if (settled) return;
		if (remaining === 0 || (workerSignal.aborted && running === 0) || (running === 0 && readyQueue.length === 0)) {
			settled = true;
			resolveCompletion();
		}
	};

	const markBlockedDependents = async (failedIndex: number): Promise<void> => {
		const queue = [...dependents[failedIndex]];
		while (queue.length > 0) {
			const index = queue.shift();
			if (index === undefined || states[index] !== "pending") continue;

			const failedDependencyIndexes = dependencyIndexes[index].filter(dependencyIndex => {
				const state = states[dependencyIndex];
				return state === "failed" || state === "blocked";
			});
			if (failedDependencyIndexes.length === 0) continue;

			const blockedResult = options.onDependencyFailure
				? await options.onDependencyFailure(items[index], index, failedDependencyIndexes)
				: undefined;
			if (blockedResult !== undefined) {
				results[index] = blockedResult;
			}
			states[index] = "blocked";
			remaining--;
			queue.push(...dependents[index]);
		}
	};

	const scheduleReady = (): void => {
		while (!settled && !workerSignal.aborted && running < limit && readyQueue.length > 0) {
			const index = readyQueue.shift();
			if (index === undefined || states[index] !== "pending") continue;

			states[index] = "running";
			running++;

			void (async () => {
				try {
					const result = await fn(items[index], index);
					results[index] = result;

					if (isSuccessful(result, index)) {
						states[index] = "succeeded";
						remaining--;
						for (const dependentIndex of dependents[index]) {
							if (states[dependentIndex] !== "pending") continue;
							remainingDependencies[dependentIndex] = Math.max(0, remainingDependencies[dependentIndex] - 1);
							if (remainingDependencies[dependentIndex] === 0) {
								readyQueue.push(dependentIndex);
							}
						}
					} else {
						states[index] = "failed";
						remaining--;
						await markBlockedDependents(index);
					}
				} catch (error) {
					if (!workerSignal.aborted) {
						abortController.abort();
						settled = true;
						rejectFirst(error);
						return;
					}
				} finally {
					running--;
					scheduleReady();
					maybeResolve();
				}
			})();
		}

		maybeResolve();
	};

	scheduleReady();

	try {
		await Promise.race([completionPromise, firstErrorPromise]);
	} catch (error) {
		// If aborted, don't rethrow - return partial results
		if (signal?.aborted) {
			return { results, aborted: true };
		}
		throw error;
	}

	return { results, aborted: signal?.aborted ?? false };
}

/**
 * Simple counting semaphore for limiting concurrency across independently-scheduled async work.
 */
export class Semaphore {
	#max: number;
	#current = 0;
	#queue: Array<() => void> = [];

	constructor(max: number) {
		this.#max = Math.max(1, max);
	}

	async acquire(): Promise<void> {
		if (this.#current < this.#max) {
			this.#current++;
			return;
		}
		const { promise, resolve } = Promise.withResolvers<void>();
		this.#queue.push(resolve);
		return promise;
	}

	release(): void {
		const next = this.#queue.shift();
		if (next) {
			next();
		} else {
			this.#current--;
		}
	}
}
